    try { JSON.parse(lines[index]); }
    catch (error) {
      jsonParseFailures++;
      failures.push({ file, line: index + 1, raw: lines[index], error: error.message });
    }
  }
}
const boundaryFiles = files.slice(0, 5);
for (const name of boundaryFiles) {
  const file = path.join(dir, name);
  const lines = fs.readFileSync(file, 'utf8').split(/\r?\n/);
  if (lines.at(-1) === '') lines.pop();
  try { JSON.parse(lines[0]); JSON.parse(lines.at(-1)); }
  catch (error) {
    console.error(`BOUNDARY_ASSERTION_FAILED ${name}: ${error.message}`);
    process.exitCode = 1;
  }
  console.log(`first/last parse asserted: ${name} (lines 1 and ${lines.length})`);
}
console.log(`fileCount=${files.length}`);
console.log(`totalLineCount=${totalLines}`);
console.log(`perFileLineCounts=${counts.join(',')}`);
console.log(`jsonParseFailures=${jsonParseFailures}`);
if (failures.length) {
  for (const failure of failures) {
    console.error(`JSON_PARSE_FAILURE file=${failure.file} line=${failure.line} error=${failure.error}`);
    console.error(failure.raw);
  }
}
if (files.length !== 24 || totalLines !== 6000 || jsonParseFailures !== 0 || counts.some(count => Number(count.split('=').at(-1)) !== 250)) {
  console.error('VALIDATION_ASSERTION_FAILED');
  process.exitCode = 1;
}
NODE
